import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * <p>
 * The original implementation configured the {@link Parser} inside a synchronized block,
 * which did not guarantee that the security‑related options (e.g. {@code setResolveEntities(false)})
 * were applied before the parser started processing the input.  This opened the possibility of
 * XML External Entity (XXE) attacks.
 * </p>
 *
 * <p>
 * The patched version creates a fresh {@link Parser} for each request and builds a dedicated
 * {@link ParserOptions} instance with entity resolution explicitly disabled.  The options are
 * passed directly to {@link Parser#parse(InputStream, ParserOptions)} so the parser is fully
 * configured before any parsing occurs.  No synchronization is required because the parser
 * instance is not shared across threads.
 * </p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  MessageBodyReader implementation (patched)
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a fresh parser instance – the parser is not thread‑safe, so we
        // must not reuse a shared instance.
        Parser parser = ATOM_ENGINE.getParser();

        // Build parser options with security in mind.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disable resolution of external entities (prevents XXE).
        options.setResolveEntities(false);
        // Additionally, prevent expansion of entity references if the API supports it.
        // This call is safe even if the method does not exist in older versions
        // because it is a no‑op in those cases.
        try {
            options.getClass()
                   .getMethod("setExpandEntityReferences", boolean.class)
                   .invoke(options, false);
        } catch (ReflectiveOperationException ignored) {
            // Method not present – the parser already disables entity expansion
            // via setResolveEntities(false). No further action required.
        }

        // Parse the input using the securely configured options.
        Document<T> doc;
        try {
            doc = parser.parse(entityStream, options);
        } catch (RuntimeException e) {
            // Convert any parsing runtime exceptions to IOException as required
            // by the JAX‑RS contract.
            throw new IOException("Failed to parse Atom XML payload", e);
        }

        // The document root is the element we need to return.
        return doc.getRoot();
    }

    // ----------------------------------------------------------------------
    //  Other abstract/provider methods (unchanged)
    // ----------------------------------------------------------------------
    // ...
}
