static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Strip query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Normalize the name to prevent traversal
    // Replace backslashes with forward slashes for uniform handling
    String normalized = name.replace('\\', '/');
    // Remove any leading '/' to avoid absolute paths
    while (normalized.startsWith("/")) {
        normalized = normalized.substring(1);
    }

    // Resolve path components and reject ".."
    Path path = Paths.get(normalized).normalize();
    for (Path part : path) {
        if (part.toString().equals("..")) {
            throw new IllegalArgumentException("Invalid file name containing path traversal sequences");
        }
    }

    // After normalization, the name must be a single file name (no separators)
    if (path.getNameCount() != 1) {
        // If there are still subdirectories, reject
        throw new IllegalArgumentException("File name must not contain directory separators");
    }

    String safeName = path.getFileName().toString();

    // Ensure the resulting file stays inside the target directory
    File dirCanonical = dir.getCanonicalFile();
    File file = new File(dirCanonical, safeName);
    // Verify canonical path
    File fileCanonical = file.getCanonicalFile();
    if (!fileCanonical.getPath().startsWith(dirCanonical.getPath() + File.separator)) {
        throw new IllegalArgumentException("Resulting file is outside the target directory");
    }

    // Duplicate handling
    int dot = safeName.lastIndexOf('.');
    String prefix = dot < 0 ? safeName : safeName.substring(0, dot);
    String suffix = dot < 0 ? "" : safeName.substring(dot);
    int index = 2;
    while (fileCanonical.exists()) {
        String newName = prefix + "-" + index++ + suffix;
        file = new File(dirCanonical, newName);
        fileCanonical = file.getCanonicalFile();
    }

    // Create parent directories if needed
    File parent = fileCanonical.getParentFile();
    if (parent != null && !parent.exists()) {
        if (!parent.mkdirs()) {
            // If mkdirs fails, throw exception
            throw new IOException("Failed to create directories for " + parent);
        }
    }

    return fileCanonical;
}
