    private static final Logger logger = LoggerFactory.getLogger(SecureRandomFactoryBean.class);

    /** Default algorithm – can be overridden via setter. */
    private String algorithm = "SHA1PRNG";

    /** Optional seed resource – no longer used for seeding. */
    private Resource seed;

