     * Creates a {@link SecureRandom} instance.
     *
     * <p>External seed data is deliberately ignored to avoid weakening the RNG.
     * The method forces an early generation of random bytes to ensure the
     * internal state is fully seeded before the instance is handed to callers.</p>
     *
     * @return a securely seeded {@link SecureRandom}
     * @throws Exception if an unexpected error occurs while creating the instance
     */
    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd;

        // -------------------------------------------------------------------
        // Choose the algorithm, falling back to the default constructor if
        // the requested algorithm is not available.
        // -------------------------------------------------------------------
        if (algorithm != null && !algorithm.trim().isEmpty()) {
            try {
                rnd = SecureRandom.getInstance(algorithm);
            } catch (NoSuchAlgorithmException ex) {
                logger.warn("Requested SecureRandom algorithm '{}' is not available. "
                        + "Falling back to default SecureRandom implementation.", algorithm, ex);
                rnd = new SecureRandom();
            }
        } else {
            rnd = new SecureRandom();
        }

        // -------------------------------------------------------------------
        // Do NOT use external seed data. If a seed resource is configured,
        // log a warning so the mis‑configuration can be corrected.
        // -------------------------------------------------------------------
        if (seed != null) {
            logger.warn("SecureRandomFactoryBean was configured with a seed resource, "
                    + "but external seeding is disabled for security reasons. The seed will be ignored.");
