    //   * When t == 0 the result is defined to be 0 (no additional bits).
    //   * v must be within the valid range [0, (1<<t)-1]; otherwise an
    //     IllegalArgumentException is thrown to avoid undefined behaviour.
    // The algorithm now follows the JPEG specification using a single
    // conditional adjustment, guaranteeing termination.

    if (t < 0 || t > 31) {
        throw new IllegalArgumentException("Parameter t out of range: " + t);
    }
    if (t == 0) {
        // No additional bits – the value is defined to be zero.
        return 0;
    }

    int max = (1 << t) - 1;
    if (v < 0 || v > max) {
        throw new IllegalArgumentException(
                "Parameter v out of range for t=" + t + ": " + v);
    }

    int vt = 1 << (t - 1);
    // If the most‑significant bit of the t‑bit value is zero, the number is
    // negative and must be sign‑extended.
    if (v < vt) {
        v += (-1 << t) + 1;
    }
    return v;
