public final class CronTab {

    // other methods ...

    /**
     * See {@link #ceil(long)}.
     *
     * This method modifies the given calendar and returns the same object.
     *
     * @throws RareOrImpossibleDateException if the date isn't hit in the 2 years after it indicates an impossible
     * (e.g. Jun 31) date, or at least a date too rare to be useful. This addresses JENKINS-41864 and was added in 2.49
     */
    public Calendar ceil(Calendar cal) {
        // Clone the input calendar to represent a date two years in the future.
        Calendar twoYearsFuture = (Calendar) cal.clone();
        twoYearsFuture.add(Calendar.YEAR, 2);

        // -----------------------------------------------------------------
        // Safety guard: prevent an infinite loop (DoS) by limiting the
        // number of iterations. The limit is deliberately generous but
        // finite; if it is exceeded we treat the situation as an
        // impossible/too‑rare date.
        // -----------------------------------------------------------------
        final int SAFETY_ITERATION_LIMIT = 10_000; // arbitrary but safe upper bound
        int iterationCount = 0;

        OUTER: while (true) {
            // Guard against runaway loops.
            if (++iterationCount > SAFETY_ITERATION_LIMIT) {
                throw new RareOrImpossibleDateException(
                        "Ceiling calculation exceeded safety iteration limit of " + SAFETY_ITERATION_LIMIT);
            }

            // If we have moved beyond the two‑year horizon, the date is considered too rare.
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            // Walk through the fields in the predefined adjustment order.
            for (CalendarField f : CalendarField.ADJUST_ORDER) {

                int cur = f.valueOf(cal);
                int next = f.ceil(this, cur);

                // No change required for this field – continue with the next one.
                if (cur == next) {
                    continue;
                }

                // Reset all lower‑order fields because a higher‑order change invalidates them.
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                // If the field cannot be satisfied (next < 0) we roll the field up
                // and start the whole adjustment process again.
                if (next < 0) {
                    f.rollUp(cal, 1);
                    f.setTo(cal, f.first(this));
                    continue OUTER;
                } else {
                    // Normal case – set the field to the next valid value.
                    f.setTo(cal, next);

                    // Some fields (e.g., day‑of‑month) may require a full re‑evaluation
                    // after being modified because they affect other fields.
                    if (f.redoAdjustmentIfModified) {
                        continue OUTER;
                    }
                }
            }

            // All fields are now consistent – exit the loop and return the adjusted calendar.
            return cal;
        }
    }

    // other methods ...

}
