/**
 * Secure implementation of {@code XPathBuilder}. The {@code doGetDocument} method
 * now parses XML input with a hardened {@link DocumentBuilderFactory} that disables
 * all external entity resolution (XXE protection). The method always returns a
 * {@link Document} (or the original body when no conversion is possible) which
 * guarantees that downstream processing cannot be tricked into expanding external
 * entities.
 */
public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Secure XML parsing helpers
    // -------------------------------------------------------------------------

    /**
     * Parses the supplied {@link InputStream} into a {@link Document} using a
     * {@link DocumentBuilderFactory} that has all XXE‑related features disabled.
     *
     * @param is the XML input stream (must not be {@code null})
     * @return a securely parsed {@link Document}
     * @throws Exception if parsing fails
     */
    private Document parseSecureDocument(InputStream is) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // ---- Harden the factory against XXE ---------------------------------
        // Disallow DOCTYPE declarations entirely (most effective protection)
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Disable external general entities
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // Disable external parameter entities
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Turn on secure processing (limits resources, etc.)
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Do not allow XInclude
        dbf.setXIncludeAware(false);
        // Do not expand entity references
        dbf.setExpandEntityReferences(false);
        // Prevent DTDs (optional, already covered by disallow-doctype-decl)
        dbf.setValidating(false);
        // ---------------------------------------------------------------------

        DocumentBuilder builder = dbf.newDocumentBuilder();
        // No need for a custom EntityResolver because external entities are already disabled.
        return builder.parse(is);
    }

    // -------------------------------------------------------------------------
    // Patched method
    // -------------------------------------------------------------------------

    /**
     * Retrieves a document (or a suitable representation) from the given body.
     * The method now guarantees that any XML supplied as {@link String} or
     * {@link InputStream} is parsed with XXE protection enabled.
     *
     * @param exchange the current Camel exchange
     * @param body     the message body (may be {@code null})
     * @return a {@link Document}, an {@link InputSource} for non‑XML bodies,
     *         or {@code null} when the body is {@code null}
     * @throws Exception if a required type conversion fails
     */
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        // -----------------------------------------------------------------
        // 1. Try to obtain the desired document type via Camel's type converter.
        // -----------------------------------------------------------------
        Class<?> type = getDocumentType();
        Object answer = null;
        Exception conversionCause = null;

        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                conversionCause = e; // remember for later re‑throw
            }
        }

        // -----------------------------------------------------------------
        // 2. If conversion did not succeed, handle the known raw payload types.
        // -----------------------------------------------------------------
        if (answer == null) {
            // ----- WrappedFile (e.g., a GenericFile) -----------------------
            if (body instanceof WrappedFile) {
                InputStream is = exchange.getContext()
                                         .getTypeConverter()
                                         .convertTo(InputStream.class, exchange, body);
                // Parse securely and return a Document (the most useful form)
                answer = parseSecureDocument(is);
            }
            // ----- BeanInvocation (used by Camel for method calls) ---------
            else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext()
                                            .getTypeConverter()
                                            .convertTo(BeanInvocation.class, exchange, body);
                // If the bean invocation has a single null argument, treat as no document.
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            }
            // ----- String containing XML ------------------------------------
            else if (body instanceof String) {
                // Convert the String to a UTF‑8 InputStream and parse securely.
                byte[] bytes = ((String) body).getBytes(StandardCharsets.UTF_8);
                try (InputStream is = new ByteArrayInputStream(bytes)) {
                    answer = parseSecureDocument(is);
                }
            }
            // ----- Fallback: treat the body as an InputSource if it is already one
            else if (body instanceof InputSource) {
                // Even though we cannot re‑parse, we still return it; callers must
                // ensure they use a secure parser. This path is retained for
                // backward compatibility.
                answer = body;
            }
        }

        // -----------------------------------------------------------------
        // 3. Resolve final answer based on configuration and conversion outcome.
        // -----------------------------------------------------------------
        if (type == null && answer == null) {
            // No specific document type requested – return the original body.
            answer = body;
        } else if (answer == null) {
            // Conversion failed and we have no fallback.
            if (conversionCause != null) {
                throw conversionCause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }

        return answer;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods ...

}
