    /**
     * Compare {@code fromVersion} and {@code toVersion}.
     * <p>
     * The method is now defensive: it tolerates {@code null}, empty strings,
     * versions with fewer or more than three components and non‑numeric components.
     * Missing or malformed components are treated as {@code 0}. This prevents
     * {@link ArrayIndexOutOfBoundsException} and {@link NumberFormatException}
     * which could otherwise be exploited for a denial‑of‑service attack.
     *
     * @param fromVersion the initial version (may be {@code null})
     * @param toVersion   the end version (may be {@code null})
     * @return a negative integer, zero, or a positive integer as {@code fromVersion}
     *         is less than, equal to, or greater than {@code toVersion}
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        // Normalise null inputs to empty strings to avoid NPEs.
        if (fromVersion == null) {
            fromVersion = "";
        }
        if (toVersion == null) {
            toVersion = "";
        }

        // Trim whitespace and split on the dot character.
        String[] fromArr = fromVersion.trim().split("\\.");
        String[] toArr   = toVersion.trim().split("\\.");

        // Compare each component sequentially. We support an arbitrary number of
        // components, but stop as soon as a difference is found.
        int maxLength = Math.max(fromArr.length, toArr.length);
        for (int i = 0; i < maxLength; i++) {
            int fromComp = safeParseComponent(fromArr, i);
            int toComp   = safeParseComponent(toArr, i);
            int diff = fromComp - toComp;
            if (diff != 0) {
                return diff;
            }
        }
        // All compared components are equal.
        return 0;
    }

    /**
     * Safely parses the component at {@code index} from the supplied array.
     * <p>
     * If the index is out of bounds or the component cannot be parsed as an
     * integer, {@code 0} is returned. This mirrors the behaviour of many version
     * comparison utilities where missing components are considered zero.
     *
     * @param parts the split version string
     * @param index the component index to parse
     * @return the integer value of the component, or {@code 0} on error
     */
    private static int safeParseComponent(String[] parts, int index) {
        if (index >= parts.length) {
            return 0; // Missing component → treat as 0
        }
        try {
            // Trim each part to guard against surrounding whitespace.
            return Integer.parseInt(parts[index].trim());
        } catch (NumberFormatException e) {
            // Malformed component → treat as 0 to keep comparison deterministic.
            return 0;
        }
    }

    // other methods ...

}
